package com.elitedarkkaiser.nubialy;
import java.nio.file.*;import org.junit.Test;import static org.junit.Assert.*;
public class SettingsCompatibilityTest {
 private static void write(Path file,String value)throws java.io.IOException {Files.write(file,value.getBytes(java.nio.charset.StandardCharsets.UTF_8));}
 @Test public void cacheInvalidatesForApkOrFirmwareChanges()throws Exception {var dir=Files.createTempDirectory("settings-cache");try{var apk=dir.resolve("Settings.apk");var marker=dir.resolve("verified");write(apk,"original");String key=SettingsCompatibility.verificationKey(apk.toFile(),"firmware-a");assertFalse(SettingsCompatibility.cached(marker.toFile(),key));write(marker,key);assertTrue(SettingsCompatibility.cached(marker.toFile(),key));assertFalse(SettingsCompatibility.cached(marker.toFile(),SettingsCompatibility.verificationKey(apk.toFile(),"firmware-b")));write(apk,"changed-length");assertFalse(SettingsCompatibility.cached(marker.toFile(),SettingsCompatibility.verificationKey(apk.toFile(),"firmware-a")));write(marker,"invalid");assertFalse(SettingsCompatibility.cached(marker.toFile(),key));}finally{try(var files=Files.walk(dir)){files.sorted(java.util.Comparator.reverseOrder()).forEach(p->{try{Files.delete(p);}catch(Exception ignored){}});}}}
}
